  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --color-bg: #f7f8fa;
  --color-surface: #ffffff;
  --color-border: #e2e5ea;
  --color-primary: #5b4cf5;
  --color-primary-light: #ede9ff;
  --color-text: #1a1d23;
  --color-text-muted: #6b7280;
  --color-icon: #9ca3af;
  --radius: 12px;
  --shadow: 0 1px 3px rgba(0,0,0,0.07), 0 4px 16px rgba(0,0,0,0.05);
  --transition: 200ms ease;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  background: var(--color-bg);
  color: var(--color-text);
  line-height: 1.6;
  min-height: 100vh;
  padding: 48px 16px 80px;
}

/* ── Page header ── */
.page-header {
  text-align: center;
  margin-bottom: 48px;
}

.page-header .eyebrow {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--color-primary);
  background: var(--color-primary-light);
  padding: 4px 12px;
  border-radius: 999px;
  margin-bottom: 16px;
}

.page-header h1 {
  font-size: clamp(1.8rem, 4vw, 2.75rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--color-text);
  margin-bottom: 12px;
}

.page-header p {
  font-size: 1.05rem;
  color: var(--color-text-muted);
  max-width: 480px;
  margin: 0 auto;
}

/* ── FAQ container ── */
.faq-list {
  max-width: 680px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

/* ── Individual FAQ item ── */
.example {
  background: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  overflow: hidden;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.example:focus-within {
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(91,76,245,0.12), var(--shadow);
}

/* ── Trigger button ── */
.faq-trigger {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 20px 24px;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  color: var(--color-text);
  font-size: 1rem;
  font-weight: 600;
  font-family: inherit;
  transition: background var(--transition);
}

.faq-trigger:hover {
  background: var(--color-bg);
}

.faq-trigger[aria-expanded="true"] {
  background: var(--color-primary-light);
  color: var(--color-primary);
}

.faq-trigger .question-text {
  flex: 1;
}

/* ── Chevron icon ── */
.faq-icon {
  flex-shrink: 0;
  width: 20px;
  height: 20px;
  color: var(--color-icon);
  transition: transform var(--transition), color var(--transition);
}

.faq-trigger[aria-expanded="true"] .faq-icon {
  transform: rotate(180deg);
  color: var(--color-primary);
}

/* ── Controlled content panel ── */
.details {
  overflow: hidden;
  max-height: 0;
  transition: max-height 300ms cubic-bezier(0.4, 0, 0.2, 1);
}

.details[aria-hidden="false"] {
  max-height: 600px;
}

.details-inner {
  padding: 0 24px 20px;
  border-top: 1px solid var(--color-border);
  color: var(--color-text-muted);
  font-size: 0.95rem;
  line-height: 1.75;
}

.details-inner p + p {
  margin-top: 10px;
}

/* ── Footer ── */
.page-footer {
  text-align: center;
  margin-top: 56px;
  font-size: 0.85rem;
  color: var(--color-text-muted);
}
