 * FAQ component — disclosure widget
 * Each .example wraps a trigger button + .details panel.
 * Follows ARIA Disclosure pattern (WAI-ARIA 1.1).
 */

const faqs = [
  {
    question: "Why does my cat knead me with their paws?",
    answer:
      "Kneading is a comforting behavior cats retain from kittenhood, when they kneaded their mother's belly to stimulate milk flow. When your cat kneads you, it's a sign they feel safe, content, and deeply attached to you. Some cats also knead soft surfaces like blankets as a self-soothing ritual before sleep.",
  },
  {
    question: "How often should I feed my cat?",
    answer:
      "Most adult cats do well with two measured meals per day—morning and evening. Kittens under six months need three to four smaller meals daily to support rapid growth. Always follow the feeding guidelines on your chosen food and adjust portions based on your cat's weight, age, and activity level. Fresh water should be available at all times.",
  },
  {
    question: "Why do cats purr, and does it always mean they're happy?",
    answer:
      "Purring is produced by rapid, rhythmic contractions of a cat's laryngeal muscles during both inhalation and exhalation. While it most often signals contentment, cats also purr when stressed, injured, or giving birth. Researchers believe purring may be self-soothing and that the vibration frequency (25–150 Hz) can even promote bone healing.",
  },
  {
    question: "Do cats need baths?",
    answer:
      "Cats are meticulous self-groomers and rarely need baths. Occasional bathing is appropriate if your cat gets into something sticky or toxic, develops a skin condition, or has mobility issues preventing self-care. When bathing is necessary, use a cat-specific shampoo, keep water lukewarm, and dry your cat thoroughly afterward to avoid chilling.",
  },
  {
    question: "Why does my cat bring me dead animals?",
    answer:
      "This is your cat's way of sharing a successful hunt with you—their beloved companion. Cats are natural predators, and bringing prey home is an instinctive gift-giving behavior rooted in how wild cats provision their family group. Indoor-only cats may substitute toys for prey as an outlet for the same instinct.",
  },
  {
    question: "How long do cats typically live?",
    answer:
      "Indoor cats live an average of 12–18 years, though many reach their mid-to-late 20s with attentive care. Outdoor cats face significantly higher risks from traffic, predators, and disease, giving them an average lifespan of 5–7 years. Regular veterinary check-ups, a balanced diet, and a safe environment are the biggest factors in longevity.",
  },
  {
    question: "Are cats truly solitary, or do they enjoy company?",
    answer:
      "Domestic cats are more socially flexible than their reputation suggests. While they are facultative solitary hunters by nature, many cats bond closely with humans and other pets when socialized early. Some cats thrive as sole companions; others benefit from a feline housemate. Individual personality, breed, and early socialization all play a role.",
  },
];

function createIcon() {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("viewBox", "0 0 20 20");
  svg.setAttribute("fill", "none");
  svg.setAttribute("stroke", "currentColor");
  svg.setAttribute("stroke-width", "2");
  svg.setAttribute("stroke-linecap", "round");
  svg.setAttribute("stroke-linejoin", "round");
  svg.setAttribute("aria-hidden", "true");
  svg.setAttribute("focusable", "false");
  svg.classList.add("faq-icon");

  const path = document.createElementNS("http://www.w3.org/2000/svg", "polyline");
  path.setAttribute("points", "5 8 10 13 15 8");
  svg.appendChild(path);
  return svg;
}

function FAQItem({ question, answer, index }) {
  const itemId = `faq-${index}`;
  const panelId = `faq-panel-${index}`;

  // Outer wrapper
  const wrapper = document.createElement("div");
  wrapper.className = "example";

  // Trigger button
  const button = document.createElement("button");
  button.className = "faq-trigger";
  button.setAttribute("aria-expanded", "false");
  button.setAttribute("aria-controls", panelId);
  button.id = itemId;

  const questionText = document.createElement("span");
  questionText.className = "question-text";
  questionText.textContent = question;

  button.appendChild(questionText);
  button.appendChild(createIcon());

  // Details panel
  const panel = document.createElement("div");
  panel.className = "details";
  panel.id = panelId;
  panel.setAttribute("role", "region");
  panel.setAttribute("aria-labelledby", itemId);
  panel.setAttribute("aria-hidden", "true");

  const inner = document.createElement("div");
  inner.className = "details-inner";
  inner.textContent = answer;

  panel.appendChild(inner);
  wrapper.appendChild(button);
  wrapper.appendChild(panel);

  // Toggle behavior
  button.addEventListener("click", () => {
    const isExpanded = button.getAttribute("aria-expanded") === "true";
    button.setAttribute("aria-expanded", String(!isExpanded));
    panel.setAttribute("aria-hidden", String(isExpanded));
  });

  return wrapper;
}

function FAQList() {
  const list = document.createElement("div");
  list.className = "faq-list";
  list.setAttribute("role", "list");

  faqs.forEach((faq, i) => {
    const item = FAQItem({ ...faq, index: i });
    item.setAttribute("role", "listitem");
    list.appendChild(item);
  });

  return list;
}

// Mount
document.addEventListener("DOMContentLoaded", () => {
  const root = document.getElementById("faq-root");
  if (root) root.appendChild(FAQList());
});
